const CAT_FOLDER: Record<string, string> = {
  vegetables: 'vegtables', vegetable: 'vegtables', fruits: 'fruits', fruit: 'fruits',
  millets: 'millets', spices: 'spices', nuts: 'nuts', 'dry-fruits': 'dryfruits', dryfruits: 'dryfruits',
  'seeds-health-mix': 'nuts', oils: 'oils', 'cold-pressed-oils': 'oils',
  ghee: 'valluvam', honey: 'valluvam', 'palm-jaggery': 'valluvam', 'dairy-ghee': 'valluvam',
};

function normKey(s: string): string {
  return s
    .toLowerCase()
    .replace(/\([^)]*\)/g, '')
    .replace(/\b(cold[- ]?pressed|fresh|organic|raw|pure|natural|farm|nattu|naatu|country|desi)\b/g, '')
    .replace(/[^a-z0-9]/g, '')
    .replace(/(250ml|500ml|1l|1litre|1000ml|250g|500g|1kg|5kg|1000g|whole|split|pack|250|500)$/, '');
}

export function resolveImageByName(name?: string, categorySlug?: string): string | null {
  if (!name) return null;
  const k = normKey(name);
  if (!k) return null;
  const folder = categorySlug ? CAT_FOLDER[categorySlug] : undefined;

  if (folder && IMG_BY_FOLDER_KEY[folder + '/' + k]) return IMG_BY_FOLDER_KEY[folder + '/' + k] as string;

  if (folder) {
    let best: string | null = null;
    let bl = 0;
    for (const fk of Object.keys(IMG_BY_FOLDER_KEY)) {
      if (!fk.startsWith(folder + '/')) continue;
      const key = fk.slice(folder.length + 1);
      if (key.length >= 4 && (k.includes(key) || key.includes(k)) && key.length > bl) {
        best = IMG_BY_FOLDER_KEY[fk] as string;
        bl = key.length;
      }
    }
    if (best) return best;
  }

  if (IMG_BY_KEY[k]) return IMG_BY_KEY[k] as string;

  let best2: string | null = null;
  let bl2 = 0;
  for (const key of Object.keys(IMG_BY_KEY)) {
    if (key.length >= 5 && (k.includes(key) || key.includes(k)) && key.length > bl2) {
      best2 = IMG_BY_KEY[key] as string;
      bl2 = key.length;
    }
  }
  return best2;
}
